parameters.jsCode:
// Parse AI response and format for backend
const aiResponse = $input.item.json.output || $input.item.json.response || $input.item.json.text || '';
const documentId = $('Workflow_Trigger_ExtractDocumentEvents').first().json.documentId;
const watchFileId = $('Workflow_Trigger_ExtractDocumentEvents').first().json.watchFileId;

try {
  let events = [];

  // Structured parser returns { events: [...] } — unwrap it
  if (aiResponse && typeof aiResponse === 'object' && Array.isArray(aiResponse.events)) {
    events = aiResponse.events;
  } else if (Array.isArray(aiResponse)) {
    events = aiResponse;
  } else {
    // Otherwise, try to parse as JSON string
    let cleanResponse = String(aiResponse).trim();

    // Remove ```json and ``` markers if present
    if (cleanResponse.includes('```')) {
      cleanResponse = cleanResponse.replace(/```json\s*/g, '').replace(/```\s*/g, '');
    }

    // Try to parse JSON
    const parsed = JSON.parse(cleanResponse);

    if (Array.isArray(parsed)) {
      events = parsed;
    } else if (parsed && Array.isArray(parsed.events)) {
      events = parsed.events;
    } else {
      throw new Error('Response is not an array and has no events property');
    }
  }

  return {
    json: {
      documentId: documentId,
      watchFileId: watchFileId,
      events: events,
      error: null
    }
  };
} catch (error) {
  // If parsing fails, return error
  return {
    json: {
      documentId: documentId,
      watchFileId: watchFileId,
      events: [],
      error: `Failed to parse AI response: ${error.message}. Response was: ${String(aiResponse).substring(0, 200)}`
    }
  };
}

