parameters.inputSchema:
{
  "type": "object",
  "required": ["events"],
  "properties": {
    "events": {
      "type": "array",
      "description": "List of extracted events (minimum 1)",
      "items": {
        "type": "object",
        "required": ["title", "start_date", "end_date", "description", "event_type", "actors", "text_extract"],
        "properties": {
          "title": {
            "type": "object",
            "required": ["fr", "en"],
            "description": "Short and explicit event title in both French and English (max 100 characters each)",
            "properties": {
              "fr": {
                "type": "string",
                "description": "Event title in French (max 100 chars)"
              },
              "en": {
                "type": "string",
                "description": "Event title in English (max 100 chars)"
              }
            },
            "additionalProperties": false
          },
          "start_date": {
            "type": "string",
            "description": "Event start date in ISO 8601 format"
          },
          "end_date": {
            "type": ["string", "null"],
            "description": "Event end date in ISO 8601 format (null if single-day or unknown)"
          },
          "description": {
            "type": "object",
            "required": ["fr", "en"],
            "properties": {
              "fr": {
                "type": "string",
                "description": "Event description in French"
              },
              "en": {
                "type": "string",
                "description": "Event description in English"
              }
            },
            "additionalProperties": false
          },
          "event_type": {
            "type": "string",
            "enum": ["commercial_business", "financial", "organizational_hr", "technological_rd", "regulatory_political", "market_competitors", "societal_environmental"],
            "description": "Category of the event"
          },
          "actors": {
            "type": "array",
            "description": "List of actors involved (minimum 1)",
            "items": {
              "type": "object",
              "required": ["name", "role"],
              "properties": {
                "name": {
                  "type": "string",
                  "description": "Actor name"
                },
                "role": {
                  "type": "string",
                  "description": "Role of the actor in the event"
                }
              },
              "additionalProperties": false
            }
          },
          "text_extract": {
            "type": ["string", "null"],
            "description": "Relevant excerpt from the document mentioning the event (null if not applicable)"
          }
        },
        "additionalProperties": false
      }
    }
  },
  "additionalProperties": false
}

